import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.CAE_xwLx.js";const c=JSON.parse('{"title":"分布式集群部署 概述","description":null,"frontmatter":{"title":"分布式集群部署 概述","description":null,"categories":["Linux 企业级运维"],"outline":[2,3],"date":"2024-11-15T00:00:00.000Z","tags":["运维","微服务","分布式","Linux"],"head":[["meta",{"name":"keywords","content":"Linux企业级运维, 分布式, 微服务, Linux, 云原生, Kubernetes, AlmaLinux, 架构"}]]},"headers":[],"relativePath":"training/linux/linux-cluster/overview.md","filePath":"training/linux/linux-cluster/overview.md","lastUpdated":1731750847000}'),n={name:"training/linux/linux-cluster/overview.md"};function i(s,e,l,d,p,g){return r(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o('<h1 id="第一章-概述" tabindex="-1">第一章 概述 <a class="header-anchor" href="#第一章-概述" aria-label="Permalink to &quot;第一章 概述&quot;">​</a></h1><blockquote><h2 id="hadoop相关项目" tabindex="-1">Hadoop相关项目 <a class="header-anchor" href="#hadoop相关项目" aria-label="Permalink to &quot;Hadoop相关项目&quot;">​</a></h2><p>Other Hadoop-related projects at Apache include:</p><ul><li><a href="https://ambari.apache.org/" target="_blank" rel="noreferrer"><strong>Ambari™</strong></a>: A web-based tool for provisioning, managing, and monitoring Apache Hadoop clusters which includes support for Hadoop HDFS, Hadoop MapReduce, Hive, HCatalog, HBase, ZooKeeper, Oozie, Pig and Sqoop. Ambari also provides a dashboard for viewing cluster health such as heatmaps and ability to view MapReduce, Pig and Hive applications visually alongwith features to diagnose their performance characteristics in a user-friendly manner.</li><li><a href="https://avro.apache.org/" target="_blank" rel="noreferrer"><strong>Avro™</strong></a>: A data serialization system.</li><li><a href="https://cassandra.apache.org/" target="_blank" rel="noreferrer"><strong>Cassandra™</strong></a>: A scalable multi-master database with no single points of failure.</li><li><a href="https://chukwa.apache.org/" target="_blank" rel="noreferrer"><strong>Chukwa™</strong></a>: A data collection system for managing large distributed systems.</li><li><a href="https://hbase.apache.org/" target="_blank" rel="noreferrer"><strong>HBase™</strong></a>: A scalable, distributed database that supports structured data storage for large tables.</li><li><a href="https://hive.apache.org/" target="_blank" rel="noreferrer"><strong>Hive™</strong></a>: A data warehouse infrastructure that provides data summarization and ad hoc querying.</li><li><a href="https://mahout.apache.org/" target="_blank" rel="noreferrer"><strong>Mahout™</strong></a>: A Scalable machine learning and data mining library.</li><li><a href="https://ozone.apache.org/" target="_blank" rel="noreferrer"><strong>Ozone™</strong></a>: A scalable, redundant, and distributed object store for Hadoop.</li><li><a href="https://pig.apache.org/" target="_blank" rel="noreferrer"><strong>Pig™</strong></a>: A high-level data-flow language and execution framework for parallel computation.</li><li><a href="https://spark.apache.org/" target="_blank" rel="noreferrer"><strong>Spark™</strong></a>: A fast and general compute engine for Hadoop data. Spark provides a simple and expressive programming model that supports a wide range of applications, including ETL, machine learning, stream processing, and graph computation.</li><li><a href="https://submarine.apache.org/" target="_blank" rel="noreferrer"><strong>Submarine</strong></a>: A unified AI platform which allows engineers and data scientists to run Machine Learning and Deep Learning workload in distributed cluster.</li><li><a href="https://tez.apache.org/" target="_blank" rel="noreferrer"><strong>Tez™</strong></a>: A generalized data-flow programming framework, built on Hadoop YARN, which provides a powerful and flexible engine to execute an arbitrary DAG of tasks to process data for both batch and interactive use-cases. Tez is being adopted by Hive™, Pig™ and other frameworks in the Hadoop ecosystem, and also by other commercial software (e.g. ETL tools), to replace Hadoop™ MapReduce as the underlying execution engine.</li><li><a href="https://zookeeper.apache.org/" target="_blank" rel="noreferrer"><strong>ZooKeeper™</strong></a>: A high-performance coordination service for distributed applications.</li></ul></blockquote>',2)]))}const u=a(n,[["render",i]]);export{c as __pageData,u as default};
